import{_ as n,C as i,o as e,c as l,a2 as o,b as s,w as a,a as c,E as d,a3 as p}from"./chunks/framework.DToEn73J.js";const S=JSON.parse('{"title":"MCP（Model Context Protocol）","description":"","frontmatter":{"title":"MCP（Model Context Protocol）","chapter":"2.2","order":2,"summary":"用 client-server 协议标准化 Agent-Tool 通信，解耦模型与工具实现。"},"headers":[],"relativePath":"02-capability-extension/mcp.md","filePath":"02-capability-extension/mcp.md","lastUpdated":1787724133000}'),m={name:"02-capability-extension/mcp.md"};function h(g,t,A,C,E,u){const r=i("Mermaid");return e(),l("div",null,[t[1]||(t[1]=o('<h1 id="mcp-model-context-protocol" tabindex="-1">MCP（Model Context Protocol） <a class="header-anchor" href="#mcp-model-context-protocol" aria-label="Permalink to &quot;MCP（Model Context Protocol）&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>MCP 是基于 JSON-RPC 2.0 的开放协议，标准化 Host 应用与工具/数据源之间的通信。它把「Function Calling 的厂商绑定」替换为可发现、可协商、可跨供应商复用的 Agent-Tool 接入层。当前规范版本为 <strong>2026-07-28</strong>。</p><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><p><strong>架构</strong>：Host（AI 应用，管理权限/上下文，每连接一个 Server 创建一个 Client）持有若干 MCP Client；每个 Client 对接一个 MCP Server（暴露 Tools/Resources/Prompts）。</p><p><strong>三种原语</strong>：</p><table tabindex="0"><thead><tr><th>原语</th><th>语义</th><th>类比</th></tr></thead><tbody><tr><td>Tools</td><td>模型可执行的带 schema 函数</td><td>Agent 的手</td></tr><tr><td>Resources</td><td>可读数据（URI + MIME）</td><td>Agent 的眼</td></tr><tr><td>Prompts</td><td>可复用提示模板</td><td>Agent 的 SOP</td></tr></tbody></table><p><strong>Transport</strong>：<code>stdio</code>（子进程，本机默认、零网络开销）与 <code>Streamable HTTP</code>（单一 <code>/mcp</code> 端点，POST+GET，可选 SSE，无状态、多客户端）。旧版 HTTP+SSE 已弃用。2026-07-28 起协议核心无状态——移除 <code>initialize</code> 握手与 <code>Mcp-Session-Id</code>，每请求在 <code>_meta</code> 自带版本/身份/能力，<code>server/discover</code> 为可选能力发现 RPC。</p>',8)),(e(),s(p,null,{default:a(()=>[d(r,{id:"mermaid-71",class:"mermaid",graph:"sequenceDiagram%0A%20%20participant%20H%20as%20Host%2FClient%0A%20%20participant%20S%20as%20MCP%20Server%0A%20%20H-%3E%3ES%3A%20server%2Fdiscover%20(%E5%8F%AF%E9%80%89)%0A%20%20S--%3E%3EH%3A%20%E7%89%88%E6%9C%AC%2F%E8%83%BD%E5%8A%9B%2Finstructions%0A%20%20H-%3E%3ES%3A%20tools%2Flist%20(%E5%B8%A6%20ttlMs%20%E7%BC%93%E5%AD%98)%0A%20%20S--%3E%3EH%3A%20%E5%B7%A5%E5%85%B7%E6%B8%85%E5%8D%95%0A%20%20H-%3E%3ES%3A%20tools%2Fcall%20(name%2C%20arguments)%0A%20%20S--%3E%3EH%3A%20%E7%BB%93%E6%9E%9C%20%2B%20%E5%8F%AF%E9%80%89%20Resource%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[c(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=o('<p><strong>动态连接生命周期</strong>：本地 stdio 由 Host spawn 子进程即连即用；远程 Streamable HTTP 走 OAuth 2.1 授权发现 → 客户端注册（CIMD 优先，DCR 已弃用）→ 令牌交换 → 调用。<code>tools/list</code> 等结果带 <code>ttlMs</code>/<code>cacheScope</code>，客户端可缓存目录。</p><h2 id="为什么" tabindex="-1">为什么 <a class="header-anchor" href="#为什么" aria-label="Permalink to &quot;为什么&quot;">​</a></h2><p>不引入 MCP，工具定义强耦合于模型厂商的 Function Calling schema，切换 provider 需重写定义，且每次请求都烧掉 Context Window 承载工具清单。MCP 把发现与执行标准化，让一个 Server 被任意 Host 复用。</p><h2 id="业界实现对照" tabindex="-1">业界实现对照 <a class="header-anchor" href="#业界实现对照" aria-label="Permalink to &quot;业界实现对照&quot;">​</a></h2><ul><li><strong>官方 TypeScript / Python SDK</strong>：<code>modelcontextprotocol/typescript-sdk</code>、<code>modelcontextprotocol/python-sdk</code>，均对齐 2026-07-28。</li><li><strong>Claude Agent SDK / OpenAI Agents SDK</strong>：通过 MCP client 把外部 Server 的 Tools 接入各自 Agent Loop。</li></ul><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="/fk-ai-agent/01-agent-basics/tool-abstraction">/01-agent-basics/tool-abstraction</a></li><li><a href="/fk-ai-agent/02-capability-extension/multi-agent">/02-capability-extension/multi-agent</a></li><li><a href="/fk-ai-agent/02-capability-extension/skill-management">/02-capability-extension/skill-management</a></li><li>官方规范：<a href="https://modelcontextprotocol.io/specification/2026-07-28/" target="_blank" rel="noreferrer">https://modelcontextprotocol.io/specification/2026-07-28/</a></li></ul><hr><p><em>最后核实日期：2026-08-26</em></p>',9))])}const _=n(m,[["render",h]]);export{S as __pageData,_ as default};
